        const nextEffort = Math.max(effort, Math.abs(heights[nr][nc] - heights[r][c]));
        if (nextEffort < dist[nr][nc]) {
          dist[nr][nc] = nextEffort;
          queue.push([nextEffort, nr, nc]);
        }
      }
    }
  }
  return dist[R - 1][C - 1];
