  let res = null;
  function backtrack(curr, path) {
    if (path.length === tickets.length + 1) {
      res = [...path];
      return true;
    }
    for (let i = 0; i < tickets.length; i++) {
      if (!used[i] && tickets[i][0] === curr) {
        used[i] = true;
        path.push(tickets[i][1]);
        if (backtrack(tickets[i][1], path)) return true;
        path.pop();
        used[i] = false;
      }
    }
    return false;
  }
  backtrack("JFK", ["JFK"]);
  return res;
}

